?><!doctype html><html lang="sr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>РАЈАЦ — управљачка евиденција налаза</title><link rel="stylesheet" href="/biljke/assets/vendor/leaflet/leaflet.min.css"><style>body{margin:0;background:#f6f8f6;color:#213d2d;font:16px system-ui}main{max-width:1120px;margin:auto;padding:22px}h1{font-size:24px}.small{font-size:14px;color:#435449}#map{height:65vh;min-height:360px;border-radius:12px}.toolbar{margin:15px 0;display:flex;gap:10px;flex-wrap:wrap}select,input{padding:9px;font:inherit}.notice{background:#fff7e5;border:1px solid #e0d1ab;border-radius:8px;padding:12px;margin:12px 0}a{color:#14683b}table{border-collapse:collapse;width:100%;background:#fff;font-size:13px}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}table{display:block;overflow:auto}</style></head><body><main><h1>ПИО „Рајац“ — интерна евиденција посматрања</h1><p class="small">Само за овлашћене кориснике. Тачне су само координате које извор није замаглио; податке о прецизности не треба претпостављати.</p><div class="notice">Интерна евиденција није јавни доказ идентитета врсте. „Needs ID“ се приказује одвојено од „Research“. Не извозити осетљиве координате у јавне ZIP/GeoJSON датотеке.</div><div class="toolbar"><select id="gr"><option value="sve">Све групе</option><option value="Plantae">Биљке</option><option value="Aves">Птице</option><option value="Fungi">Гљиве</option><option value="Insecta">Инсекти</option><option value="Mammalia">Сисари</option></select><select id="q"><option value="sve">Сви статуси</option><option value="research">Research</option><option value="needs_id">Needs ID</option></select><input id="find" placeholder="Научни назив / посматрач"></div><div id="meta" class="small">Учитавање…</div><div id="map"></div><h2>Списак налаза</h2><table><thead><tr><th>ID</th><th>Таксон</th><th>Датум</th><th>Квалитет</th><th>Координате</th><th>GPS прецизност</th></tr></thead><tbody id="rows"></tbody></table></main><script src="/biljke/assets/vendor/leaflet/leaflet.min.js"></script><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const m=L.map('map').setView([44.14,20.225],12);L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:18,attribution:'Esri World Imagery'}).addTo(m);let pts=L.layerGroup().addTo(m);let all=[];
fetch('records.php',{cache:'no-store',credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(d=>{all=d.records;draw();}).catch(e=>document.getElementById('meta').textContent='Није доступно: '+e.message);
function draw(){pts.clearLayers();let g=document.getElementById('gr').value,q=document.getElementById('q').value,s=document.getElementById('find').value.toLowerCase();const selected=all.filter(o=>(g==='sve'||o.grupa_taxon===g)&&(q==='sve'||o.quality_grade===q)&&((o.naucni+' '+o.korisnik).toLowerCase().includes(s)));document.getElementById('meta').textContent=selected.length+' записа · Тачке са доступним јавним координатама приказане само где нису замагљене.';document.getElementById('rows').innerHTML=selected.map(o=>'<tr><td>'+esc(o.obs_id)+'</td><td>'+esc(o.naucni)+'</td><td>'+esc(o.datum)+'</td><td>'+esc(o.quality_grade)+'</td><td>'+esc(o.location_status==='public_exact' ? (o.lat+', '+o.lng):'Непозната/замагљена')+'</td><td>'+esc(o.positional_accuracy??'—')+'</td></tr>').join('');for(let o of selected)if(o.location_status==='public_exact'&&Number.isFinite(o.lat)&&Number.isFinite(o.lng)){L.circleMarker([o.lat,o.lng],{radius:5,color:'#12634d'}).bindPopup('<strong>'+esc(o.naucni)+'</strong><div>'+esc(o.quality_grade)+'</div><div><a href="https://www.inaturalist.org/observations/'+encodeURIComponent(o.obs_id)+'" rel="noopener noreferrer">Изворни запис</a></div>').addTo(pts);}}
for(let id of ['gr','q','find'])document.getElementById(id).addEventListener(id==='find'?'input':'change',draw);
</script></body></html>